window.bookSummaryJSON = "<p><i>Once upon a time, a girl found a magical puppy, and her life was never the same again.</i><br> <br> Nina Popoca needs help.<br> <br> So, so much of it.<br> <br> The only place she can find that help is on a sprawling ranch in Colorado. A place hiding more than a community filled with magical creatures trying to live their lives in safety and in peace. A village that might hold the answers to questions she’s had her entire life.<br> <br> And if that ranch is owned by her best friend’s hunky cousin?<br> <br> There are worse things in the world than having to live right by Henri Blackrock.</p>"; 
